            } else if (left.getOrDefault(x + 1, 0) > 0 && left.getOrDefault(x + 2, 0) > 0) {
                left.merge(x + 1, -1, Integer::sum);
                left.merge(x + 2, -1, Integer::sum);
                ends.merge(x + 2, 1, Integer::sum);
            } else return false;
        }
        return true;
    }
}

